item.test:
/* Self-grading: spec §3 row 1 + §4. Runs first; stamps articleId for 3/4/5. */
pm.test("1. POST /article/ -> 201", function () {
    pm.response.to.have.status(201);
});
pm.test("1. body is the stored article (spec columns present)", function () {
    var json = pm.response.json();
    pm.expect(json).to.be.an('object');
    ["Id","Title","Content","Category","Created_date","Updated_date","Status"]
        .forEach(function (k) { pm.expect(json).to.have.property(k); });
});
pm.test("1. payload round-trips (title & status echoed)", function () {
    var json = pm.response.json();
    var sent = JSON.parse(pm.request.body.raw);
    pm.expect(json.Title).to.eql(sent.title);
    pm.expect(json.Status).to.eql(sent.status);
});
pm.test("1. captured new id for the rest of the flow", function () {
    var json = pm.response.json();
    pm.expect(json.Id).to.be.a('number');
    pm.collectionVariables.set('articleId', String(json.Id));
});

/* Self-grading: spec §3 row 2 — array body + X-Total-Count. */
pm.test("2. GET /article/{limit}/{offset} -> 200", function () {
    pm.response.to.have.status(200);
});
pm.test("2. body is a JSON array of articles", function () {
    pm.expect(pm.response.json()).to.be.an('array');
});
pm.test("2. X-Total-Count header present, numeric, >= page length", function () {
    var hdr = pm.response.headers.get("X-Total-Count");
    pm.expect(hdr, "X-Total-Count header").to.not.be.undefined;
    var total = parseInt(hdr, 10);
    pm.expect(isNaN(total)).to.eql(false);
    pm.expect(total).to.be.at.least(pm.response.json().length);
});
pm.test("2. rows expose title/content/category/status", function () {
    var rows = pm.response.json();
    if (rows.length > 0) {
        ["Title","Content","Category","Status"].forEach(function (k) {
            pm.expect(rows[0]).to.have.property(k);
        });
    }
});

/* Self-grading: spec §3 row 3. */
pm.test("3. GET /article/{id} -> 200", function () {
    pm.response.to.have.status(200);
});
pm.test("3. returns the requested article with spec fields", function () {
    var json = pm.response.json();
    pm.expect(json).to.be.an('object');
    var id = pm.collectionVariables.get("articleId") || pm.variables.get("articleId");
    pm.expect(json.Id).to.eql(parseInt(id, 10));
    ["Title","Content","Category","Created_date","Updated_date","Status"]
        .forEach(function (k) { pm.expect(json).to.have.property(k); });
});
pm.test("3. status is one of publish|draft|thrash", function () {
    pm.expect(pm.response.json().Status).to.be.oneOf(["publish","draft","thrash"]);
});

