/* Self-grading: spec §3 row 4 (PUT accepted; PATCH also supported). */
pm.test("4. PUT /article/{id} -> 200", function () {
    pm.response.to.have.status(200);
});
pm.test("4. response reflects the updated payload", function () {
    var json = pm.response.json();
    var sent = JSON.parse(pm.request.body.raw);
    pm.expect(json.Title).to.eql(sent.title);
    pm.expect(json.Status).to.eql(sent.status);
});

/* Self-grading: spec §3 row 5 — soft delete keeps the row, Status -> thrash. */
pm.test("5. DELETE /article/{id} -> 204", function () {
    pm.response.to.have.status(204);
});
pm.test("5. soft delete: GET after returns status=thrash", function () {
    var id = pm.collectionVariables.get("articleId") || pm.variables.get("articleId");
    var base = pm.collectionVariables.get("baseUrl") || pm.variables.get("baseUrl");
    pm.sendRequest(base + "/article/" + id, function (err, res) {
        if (err) { pm.expect.fail("GET after delete failed: " + err); return; }
        pm.expect(res.code).to.eql(200);
        pm.expect(res.json().Status).to.eql("thrash");
    });
});

/* Self-grading: spec §4 — title<20, content<200, category<3, bad status -> 422. */
pm.test("6. invalid payload -> 422", function () {
    pm.response.to.have.status(422);
});
pm.test("6. error envelope present", function () {
    pm.expect(pm.response.json()).to.have.property("error");
});
